package main

import (
	"fmt"
	"sort"
)

func main() {
	scores := map[string]int{
		"charlie": 85,
		"alice":   92,
		"bob":     78,
		"dave":    90,
	}

	// Ranging directly gives an UNSPECIFIED, randomized order.
	// fmt.Println(scores) sorts by key for display, but `range` does NOT.

	// Step 1: collect the keys into a slice.
	keys := make([]string, 0, len(scores)) // pre-size to avoid reallocs
	for k := range scores {
		keys = append(keys, k)
	}

	// Step 2: sort the keys for a stable, deterministic order.
	sort.Strings(keys)

	// Step 3: iterate in sorted key order.
	for _, k := range keys {
		fmt.Printf("%s: %d\n", k, scores[k])
	}
}

package main

import (
	"fmt"
	"strings"
)

func main() {
	text := "go map map go go hash"

	// A nil map can be READ but NOT written:
	var nilMap map[string]int
	fmt.Println("read nil map:", nilMap["go"]) // 0, no panic
	// nilMap["go"] = 1                        // would panic: assignment to entry in nil map

	// Initialize with make before writing.
	counts := make(map[string]int)
	for _, w := range strings.Fields(text) {
		counts[w]++ // missing key reads as 0, then increments
	}

	// comma-ok distinguishes "absent" from "present with zero value".
	if n, ok := counts["go"]; ok {
		fmt.Printf("go appears %d times\n", n)
	}
	if _, ok := counts["python"]; !ok {
		fmt.Println("python not found")
	}

	// delete removes a key; deleting an absent key is a safe no-op.
	delete(counts, "hash")
	delete(counts, "missing") // no-op, no panic

	fmt.Println("map count:", counts["map"], "hash present:", func() bool { _, ok := counts["hash"]; return ok }())
}

package main

import (
	"fmt"
	"sync"
)

// counter is a concurrency-safe wrapper around a map.
type counter struct {
	mu sync.RWMutex
	m  map[string]int
}

func newCounter() *counter { return &counter{m: make(map[string]int)} }

func (c *counter) inc(k string) {
	c.mu.Lock() // exclusive lock for writes
	c.m[k]++
	c.mu.Unlock()
}

func (c *counter) get(k string) int {
	c.mu.RLock() // shared lock for reads
	defer c.mu.RUnlock()
	return c.m[k]
}

func main() {
	// UNSAFE (would crash with 'fatal error: concurrent map writes'):
	//   bad := map[string]int{}
	//   for i := 0; i < 100; i++ { go func() { bad["x"]++ }() }

	c := newCounter()
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c.inc("x") // serialized by the mutex
		}()
	}
	wg.Wait()
	fmt.Println("x =", c.get("x"))
}
